const state={lang:localStorage.getItem('finec_lang')==='en'?'en':'fr',token:sessionStorage.getItem('finec_token'),user:null,page:'overview',cache:{},search:'',mobile:false};
const t=(k)=>i18n[state.lang][k]??k;
const money=(v)=>new Intl.NumberFormat(state.lang==='fr'?'fr-FR':'en-US',{maximumFractionDigits:0}).format(Number(v||0))+' XAF';
const num=(v)=>new Intl.NumberFormat(state.lang==='fr'?'fr-FR':'en-US').format(Number(v||0));
const date=(s)=>s?new Intl.DateTimeFormat(state.lang==='fr'?'fr-FR':'en-GB',{day:'2-digit',month:'short',year:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(s)): '—';
const esc=(s)=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const attr=(s)=>esc(s);
const cap=(s)=>esc(t(s)||s);
const badge=(s)=>{const names={LOW:t('low'),MEDIUM:t('medium'),HIGH:t('high')};return `<span class="status ${attr(s)}">${esc(names[s]||t(s))}</span>`};
const translateReason=(s)=>({
 'Large amount — manual compliance review':state.lang==='fr'?'Montant élevé — examen manuel par la conformité':s,
 'High-risk customer transaction':state.lang==='fr'?'Opération d’un client présentant un risque élevé':s
}[s]||s);
const glLabel=(label)=>({
 'Cash on hand (simulation)':'Espèces en caisse (simulation)',
 'Loans receivable (simulation)':'Créances sur crédits (simulation)',
 'Customer deposits payable':'Dépôts à restituer aux clients',
 'External payment clearing (simulation)':'Compensation externe (simulation)',
 'Demo opening capital':'Capital initial fictif',
 'Loan interest income (simulation)':'Produits d’intérêts (simulation)'
}[label]||label);
const can=(permission)=>state.user?.permissions.includes(permission);
const icon=(name)=>{const paths={overview:'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><rect x="14" y="14" width="7" height="7" rx="1"/>',customers:'<circle cx="9" cy="8" r="4"/><path d="M3 21v-3a6 6 0 0 1 12 0v3M17 4a4 4 0 0 1 0 8m1 3a5 5 0 0 1 3 5"/>',accounts:'<rect x="3" y="5" width="18" height="15" rx="2"/><path d="M3 9h18M7 15h4"/>',operations:'<path d="M4 7h16m-5-4 5 4-5 4M20 17H4m5-4-5 4 5 4"/>',loans:'<path d="M3 10 12 3l9 7M5 10v10h14V10M9 13h6m-6 4h6"/>',approvals:'<rect x="4" y="3" width="16" height="19" rx="2"/><path d="m8 14 3 3 5-6M8 7h8"/>',compliance:'<path d="M12 2 4 5v6c0 5 3 9 8 11 5-2 8-6 8-11V5z"/><path d="m9 12 2 2 4-4"/>',branches:'<path d="M3 21V9l9-6 9 6v12M7 21v-9h10v9M10 15h4"/>',reports:'<path d="M3 3v18h18M7 16l4-5 4 2 5-7"/>',audit:'<path d="M5 4h14v17H5zM9 8h6M9 12h6M9 16h4"/>',products:'<rect x="3" y="3" width="8" height="8" rx="1"/><rect x="13" y="3" width="8" height="8" rx="1"/><rect x="3" y="13" width="8" height="8" rx="1"/><rect x="13" y="13" width="8" height="8" rx="1"/>',settings:'<path d="M12 3v2m0 14v2M3 12h2m14 0h2M5.6 5.6 7 7m10 10 1.4 1.4M18.4 5.6 17 7M7 17l-1.4 1.4"/><circle cx="12" cy="12" r="5"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.overview}</svg>`};
const navGroups=[['group1',['overview','customers','accounts','operations','loans']],['group2',['approvals','compliance','branches']],['group3',['reports','audit','products','settings']]];

async function api(path,{method='GET',body,raw=false}={}){
 const res=await fetch('/api'+path,{method,headers:{...(state.token?{Authorization:'Bearer '+state.token}:{}),...(body?{'Content-Type':'application/json'}:{})},body:body?JSON.stringify(body):undefined});
 if(res.status===401 && !path.startsWith('/auth/')){sessionStorage.removeItem('finec_token');state.token=null;state.user=null;render();throw new Error(t('sessionExpired'))}
 if(!res.ok){let data={};try{data=await res.json()}catch{}throw new Error(typeof data.detail==='string'?data.detail:JSON.stringify(data.detail??t('error')))}
 return raw?res:res.json();
}
async function load(){const [me,dash,customers,accounts,operations,loans,alerts,branches,ledger,check,catalog,settings,audit]=await Promise.all([
 api('/me'),api('/reports/dashboard'),api('/customers'),api('/accounts'),api('/operations'),api('/loans'),api('/alerts'),api('/branches'),api('/reports/ledger'),api('/reports/check'),api('/catalog'),api('/settings'),api('/audit')]);
 state.user=me;state.cache={dash,customers,accounts,operations,loans,alerts,branches,ledger,check,catalog,settings,audit};
}
const topName=(page)=>t(({overview:'overview',customers:'customerTitle',accounts:'accountsTitle',operations:'opsTitle',loans:'loanTitle',approvals:'approvalTitle',compliance:'complianceTitle',branches:'branchTitle',reports:'reportTitle',audit:'auditTitle',products:'productsTitle',settings:'settingsTitle'})[page]);
const topSub=(page)=>t(({overview:'platform',customers:'customerSub',accounts:'accountsSub',operations:'opsSub',loans:'loanSub',approvals:'approvalSub',compliance:'complianceSub',branches:'branchSub',reports:'reportSub',audit:'auditSub',products:'productsSub',settings:'settingsSub'})[page]);
const navHTML=()=>`<aside class="sidebar ${state.mobile?'open':''}"><div class="logo"><div class="brand-mark">F</div><div><div class="logo-title">FINEC <span style="color:#40d6a3">ONE</span></div><div class="logo-small">CORE BANKING</div></div></div><div class="sidebar-scroll">${navGroups.map(([label,items])=>`<div class="nav-section">${t(label)}</div>${items.map(key=>`<button class="nav-btn ${state.page===key?'active':''}" data-page="${key}">${icon(key)}<span>${t(key)}</span>${key==='approvals'&&state.cache.dash?.kpis.pending?`<span class="nav-count">${state.cache.dash.kpis.pending}</span>`:''}</button>`).join('')}`).join('')}</div><div class="sidebar-footer"><div class="demo-signal"><span class="pulse"></span><div><strong>${t('demo')}</strong><div style="color:#92c2ae">${t('fake')}</div></div></div></div></aside>`;
const pageHeader=(buttons='')=>`<div class="page-heading"><div><div class="eyebrow">FINEC S.A. / ${t('scope')}</div><h1 class="page-title">${topName(state.page)}</h1><p class="subtitle">${topSub(state.page)}</p></div><div class="actions">${buttons}</div></div>`;
const btn=(text,action,variant='primary',params='')=>`<button class="btn ${variant}" data-action="${action}" ${params}>${text}</button>`;
const getFiltered=(arr,columns)=>{let term=state.search.toLocaleLowerCase();return term?arr.filter(x=>columns.some(c=>String(x[c]??'').toLocaleLowerCase().includes(term))):arr};
const tb=(headers,content)=>`<div class="table-scroll"><table class="data-table"><thead><tr>${headers.map(h=>`<th>${h}</th>`).join('')}</tr></thead><tbody>${content||`<tr><td colspan="${headers.length}" class="empty">${t('noData')}</td></tr>`}</tbody></table></div>`;
const short=(s)=>String(s||'').slice(0,18);
const kpi=(symbol,label,value,meta)=>`<div class="kpi"><div class="icon-circle">${symbol}</div><div class="kpi-label">${label}</div><div class="kpi-value">${value}</div><div class="kpi-meta">${meta}</div></div>`;

function sparkChart(data){let series=data.length?data:[{amount:0}];while(series.length<7)series.unshift({amount:0,day:''});const max=Math.max(...series.map(x=>x.amount),1);const width=700,height=170,pts=series.map((x,i)=>[16+i*(width-32)/(series.length-1),height-12-(x.amount/max)*135]);const path=pts.map(([x,y],i)=>(i?'L':'M')+x.toFixed(1)+','+y.toFixed(1)).join(' ');return `<svg viewBox="0 0 700 210" preserveAspectRatio="none" aria-label="Transaction activity chart"><defs><linearGradient id="areaFill" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#23b18b" stop-opacity=".25"/><stop offset="100%" stop-color="#23b18b" stop-opacity=".005"/></linearGradient></defs>${[30,75,120,165].map(y=>`<line x1="0" y1="${y}" x2="700" y2="${y}" stroke="#e6eee9" stroke-dasharray="3,6"/>`).join('')}<path d="${path} L ${pts[pts.length-1][0]},183 L ${pts[0][0]},183 Z" fill="url(#areaFill)"/><path d="${path}" stroke="#1ba47b" stroke-width="3.5" fill="none" stroke-linecap="round" stroke-linejoin="round"/>${pts.map(([x,y])=>`<circle cx="${x}" cy="${y}" r="4" fill="#fff" stroke="#1ba47b" stroke-width="2"/>`).join('')}${series.filter((_,i)=>i%Math.max(1,Math.ceil(series.length/6))===0).map(d=>{let p=pts[series.indexOf(d)];return `<text x="${p[0]}" y="204" text-anchor="middle" font-size="10" fill="#92a79d">${(d.day||'').slice(5)}</text>`}).join('')}</svg>`}
function donutChart(products){const shades=['#166d58','#2fad84','#8bcdb1','#e4b65b'];const total=products.reduce((s,p)=>s+p.deposits,0)||1;let off=0;const stops=products.map((p,i)=>{const pct=p.deposits/total*100;const s=`${shades[i%4]} ${off}% ${off+pct}%`;off+=pct;return s}).join(',');return `<div class="donut-layout"><div class="donut" style="background:conic-gradient(${stops||'#d8eee5 0% 100%'})"><div class="donut-inner"><b>${products.length}</b><span>${t('product')}</span></div></div><div class="legend">${products.map((p,i)=>`<div class="legend-line"><div class="legend-key"><span class="legend-dot" style="background:${shades[i%4]}"></span>${cap(p.product)}</div><b>${Math.round(p.deposits/total*100)}%</b></div>`).join('')}</div></div>`}
function overview(){const {dash,operations,check}=state.cache;let k=dash.kpis;return pageHeader(btn('+ '+t('newOp'),'open-operation'))+`<div class="welcome-card"><div><h2>${t('ready')}</h2><p>${t('welcomeSub')}</p></div><div class="welcome-visual">◈</div></div><div class="grid kpi-grid">${kpi('♙',t('clientsTotal'),num(k.clients),t('customersCaption'))}${kpi('◫',t('deposits'),money(k.deposits),t('activeAccounts')+': '+num(k.active_accounts))}${kpi('↗',t('portfolio'),money(k.loan_portfolio),t('loans'))}${kpi('◎',t('pendingTotal'),num(k.pending),t('alertsTotal')+': '+num(k.alerts))}</div><div class="grid content-grid"><section class="panel"><div class="panel-head"><h3>${t('cashflow')}</h3><span class="panel-note">${t('cashflowSub')}</span></div><div class="chart-area">${sparkChart(dash.activity)}</div></section><section class="panel"><div class="panel-head"><h3>${t('distribution')}</h3></div>${donutChart(dash.products)}</section></div><div class="grid content-grid"><section class="panel"><div class="panel-head"><h3>${t('lastOps')}</h3><button class="btn small" data-page="operations">${t('seeAll')}</button></div>${tb([t('date'),t('type'),t('amount'),t('status')],operations.slice(0,5).map(o=>`<tr><td>${date(o.created_at)}</td><td><strong>${cap(o.kind)}</strong></td><td class="number">${money(o.amount)}</td><td>${badge(o.status)}</td></tr>`).join(''))}</section><section class="panel"><div class="panel-head"><h3>${t('agencyPerformance')}</h3><button class="btn small" data-page="branches">${t('seeAll')}</button></div>${dash.branches.slice(0,5).map(b=>`<div class="metric-line"><span><b>${esc(b.name)}</b><div class="small-label">${num(b.customers)} ${t('customers').toLowerCase()}</div></span><strong>${money(b.deposits)}</strong></div>`).join('')}<div class="section-gap small-label">${check.balanced?'✓ '+t('balanced'):'⚠ '+t('invalid')} · ${check.entries_checked} ${t('journalCount').toLowerCase()}</div></section></div><div class="insight-bar"><div><h3>${t('shortcut')}</h3><p>${t('nonProd')}</p></div><div class="actions">${btn('+ '+t('newDeposit'),'open-deposit','gold')}${btn('→ '+t('newTransfer'),'open-transfer','gold')}${btn(t('reviewPending'),'go-approvals','btn')}</div></div>`}
function customersView(){let data=getFiltered(state.cache.customers,['full_name','customer_no','phone']);return pageHeader(can('customers.write')?btn('+ '+t('newCustomer'),'open-customer'):'')+`<div class="grid kpi-grid">${kpi('♙',t('clientsTotal'),num(state.cache.customers.length),t('scope'))}${kpi('✓',t('verified'),num(state.cache.customers.filter(x=>x.kyc_status==='verified').length),t('kycStatus'))}${kpi('!',t('pendingKyc'),num(state.cache.customers.filter(x=>x.kyc_status==='pending').length),t('compliance'))}${kpi('⚑',t('high'),num(state.cache.customers.filter(x=>x.risk_level==='HIGH').length),t('risk'))}</div><div class="toolbar">${searchBox()}<span class="panel-note">${num(data.length)} ${t('customers').toLowerCase()}</span></div><section class="panel">${tb([t('customerNo'),t('name'),t('branch'),t('kycStatus'),t('risk'),t('accountsCount'),t('actions')],data.map(c=>`<tr><td class="mono"><strong>${esc(c.customer_no)}</strong></td><td><strong>${esc(c.full_name)}</strong><br><span class="small-label">${esc(c.phone)}</span></td><td>${esc(c.branch_name)}</td><td>${badge(c.kyc_status)}</td><td>${badge(c.risk_level)}</td><td>${c.account_count}</td><td><div class="op-links">${can('kyc.write')?btn(t('kyc'),'open-kyc','small',`data-id="${c.id}"`):''}${can('accounts.write')&&c.kyc_status==='verified'?btn('+'+t('account'),'open-account','small',`data-id="${c.id}"`):''}</div></td></tr>`).join(''))}</section>`}
function accountsView(){let data=getFiltered(state.cache.accounts,['account_no','customer_name']);return pageHeader(can('accounts.write')?btn('+ '+t('newAccount'),'open-account'):'')+`<div class="toolbar">${searchBox()}<span class="panel-note">${num(data.length)} ${t('accounts').toLowerCase()}</span></div><section class="panel">${tb([t('accountNo'),t('customer'),t('product'),t('branch'),t('balance'),t('status'),t('actions')],data.map(a=>`<tr><td class="mono"><strong>${esc(a.account_no)}</strong></td><td>${esc(a.customer_name)}</td><td>${cap(a.product)}</td><td>${esc(a.branch_name)}</td><td class="number">${money(a.balance)}</td><td>${badge(a.status)}</td><td><div class="op-links">${btn(t('statement'),'open-statement','small',`data-id="${a.id}"`)}${can('accounts.write')?btn(a.status==='frozen'?t('unfreeze'):t('freeze'),'toggle-account','small',`data-id="${a.id}" data-status="${a.status==='frozen'?'active':'frozen'}"`):''}</div></td></tr>`).join(''))}</section>`}
function operationsView(){let data=getFiltered(state.cache.operations,['reference','source_no','destination_no','kind','status']);return pageHeader(can('operations.write')?btn('+ '+t('newOp'),'open-operation'):'')+`<div class="toolbar">${searchBox()}<span class="panel-note">${num(data.length)} ${t('operations').toLowerCase()}</span></div><section class="panel">${tb([t('date'),t('id'),t('type'),t('source'),t('destination'),t('amount'),t('status')],data.map(o=>`<tr><td>${date(o.created_at)}</td><td class="mono"><strong>${esc(o.reference)}</strong></td><td>${cap(o.kind)}<br><span class="small-label">${esc(o.channel)}</span></td><td class="mono">${esc(o.source_no||'—')}</td><td class="mono">${esc(o.destination_no||'—')}</td><td class="number">${money(o.amount)}</td><td>${badge(o.status)}</td></tr>`).join(''))}</section><p class="side-note">${t('opCreateSub')} ${t('nonProd')}</p>`}
function loansView(){let data=getFiltered(state.cache.loans,['loan_no','customer_name','product','status']);return pageHeader(can('loans.write')?btn('+ '+t('newLoan'),'open-loan'):'')+`<div class="toolbar">${searchBox()}<span class="panel-note">${num(data.length)} ${t('loans').toLowerCase()}</span></div><section class="panel">${tb([t('loanNo'),t('customer'),t('product'),t('principal'),t('outstanding'),t('installment'),t('status'),t('actions')],data.map(l=>`<tr><td class="mono"><strong>${esc(l.loan_no)}</strong></td><td>${esc(l.customer_name)}</td><td>${cap(l.product)}</td><td class="number">${money(l.principal)}</td><td><strong>${money(l.outstanding)}</strong><div class="loan-progress"><div style="width:${Math.round((l.principal-l.outstanding)/l.principal*100)}%"></div></div></td><td>${money(l.monthly_payment)}<br><span class="small-label">${l.rate}% / ${l.term_months}m</span></td><td>${badge(l.status)}</td><td>${l.status==='active'&&can('operations.write')?btn(t('repay'),'open-repay','small',`data-id="${l.id}"`):'—'}</td></tr>`).join(''))}</section><p class="side-note">${t('loanRepaySub')}</p>`}
function approvalsView(){const ops=state.cache.operations.filter(x=>x.status==='pending'),loans=state.cache.loans.filter(x=>x.status==='pending');const has=can('operations.approve')||can('loans.approve');const buttons=(kind,id,maker)=>{if(!has)return '—';const disabled=Number(maker)===Number(state.user.id)?'disabled title="Maker-checker separation"':'';return `<div class="op-links">${btn(t('approve'),'decide','small primary',`data-kind="${kind}" data-id="${id}" data-decision="approve" ${disabled}`)}${btn(t('reject'),'decide','small danger',`data-kind="${kind}" data-id="${id}" data-decision="reject" ${disabled}`)}</div>`};return pageHeader()+`<div class="banner-info">⚠ ${t('approvalWarning')}</div><section class="panel"><div class="panel-head"><h3>${t('operations')} (${ops.length})</h3></div>${tb([t('date'),t('id'),t('type'),t('amount'),t('maker'),t('actions')],ops.map(o=>`<tr><td>${date(o.created_at)}</td><td class="mono">${esc(o.reference)}</td><td>${cap(o.kind)}</td><td class="number">${money(o.amount)}</td><td>${esc(o.creator_name)}</td><td>${buttons('operation',o.id,o.created_by)}</td></tr>`).join(''))}</section><section class="panel section-gap"><div class="panel-head"><h3>${t('loans')} (${loans.length})</h3></div>${tb([t('loanNo'),t('customer'),t('principal'),t('rate'),t('maker'),t('actions')],loans.map(l=>`<tr><td class="mono">${esc(l.loan_no)}</td><td>${esc(l.customer_name)}</td><td>${money(l.principal)}</td><td>${l.rate}%</td><td>#${l.created_by}</td><td>${buttons('loan',l.id,l.created_by)}</td></tr>`).join(''))}</section>`}
function complianceView(){const alerts=state.cache.alerts,kyc=state.cache.customers.filter(c=>c.kyc_status==='pending');return pageHeader()+`<div class="banner-info">${t('riskBanner')}</div><div class="grid kpi-grid">${kpi('!',t('alertsTotal'),num(alerts.filter(x=>x.status==='open').length),t('alerts'))}${kpi('▤',t('pendingKyc'),num(kyc.length),t('kyc'))}${kpi('⚑',t('high'),num(state.cache.customers.filter(c=>c.risk_level==='HIGH').length),t('risk'))}${kpi('◈',t('transactionsTotal'),num(state.cache.dash.kpis.transactions),t('scope'))}</div><section class="panel"><div class="panel-head"><h3>${t('pendingKyc')}</h3></div>${tb([t('customerNo'),t('name'),t('risk'),t('created'),t('actions')],kyc.map(c=>`<tr><td>${esc(c.customer_no)}</td><td><strong>${esc(c.full_name)}</strong></td><td>${badge(c.risk_level)}</td><td>${date(c.created_at)}</td><td>${can('kyc.write')?btn(t('verify'),'open-kyc','small',`data-id="${c.id}"`):'—'}</td></tr>`).join(''))}</section><section class="panel section-gap"><div class="panel-head"><h3>${t('alerts')}</h3></div>${tb([t('date'),t('customer'),t('reason'),t('risk'),t('status'),t('actions')],alerts.map(a=>`<tr><td>${date(a.created_at)}</td><td>${esc(a.customer_name)}</td><td>${esc(translateReason(a.reason))}</td><td>${badge(a.severity)}</td><td>${badge(a.status)}</td><td>${can('alerts.write')?`<div class="op-links">${btn(t('review'),'alert-review','small',`data-id="${a.id}"`)}${btn(t('escalate'),'alert-escalate','small',`data-id="${a.id}"`)}</div>`:'—'}</td></tr>`).join(''))}</section>`}
function branchesView(){const data=state.cache.dash.branches, max=Math.max(...data.map(b=>b.deposits),1);return pageHeader()+`<div class="grid kpi-grid">${kpi('⌂',t('branchesTotal'),num(data.length),t('scope'))}${kpi('♙',t('clientsTotal'),num(state.cache.customers.length),t('customers'))}${kpi('◫',t('deposits'),money(state.cache.dash.kpis.deposits),t('accounts'))}${kpi('↗',t('portfolio'),money(state.cache.dash.kpis.loan_portfolio),t('loans'))}</div><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(280px,1fr))">${state.cache.branches.map(b=>{const stat=data.find(x=>x.code===b.code)||{deposits:0,customers:0};return `<div class="panel"><div class="inline-space"><div><div class="eyebrow">FINEC • ${esc(b.code)}</div><h3 style="margin:0">${esc(b.name)}</h3><p class="small-label">${esc(b.city)}</p></div><div class="icon-circle" style="font-size:24px">⌂</div></div><div class="metric-line"><span>${t('clientsTotal')}</span><b>${stat.customers}</b></div><div class="metric-line"><span>${t('deposits')}</span><b>${money(stat.deposits)}</b></div><div class="branch-bar"><div style="width:${stat.deposits/max*100}%"></div></div></div>`}).join('')}</div>`}
function reportsView(){const g=state.cache.ledger,c=state.cache.check;const sum=key=>g.reduce((a,b)=>a+b[key],0);return pageHeader(btn(t('export'),'export','',`data-dataset="ledger"`))+`<div class="grid kpi-grid">${kpi('✓',t('balanced'),c.balanced?'OK':'⚠',t('proof'))}${kpi('⊞',t('journalCount'),num(c.entries_checked),t('coreHealth'))}${kpi('◈',t('auditValid'),c.audit_chain_valid?'OK':'⚠',t('integrity'))}${kpi('⚠',t('invalid'),num(c.issues.length),t('verification'))}</div><div class="banner-info">${t('checkNote')}</div><section class="panel"><div class="panel-head"><h3>${t('trialBalance')}</h3><button class="btn small" data-action="check-ledger">↻ ${t('verification')}</button></div>${tb([t('gl'),t('category'),t('debit'),t('credit')],g.map(l=>`<tr><td><strong>${esc(l.code)} — ${esc(state.lang==='fr'?glLabel(l.label):l.label)}</strong></td><td>${cap(l.category)}</td><td class="number">${money(l.debit)}</td><td class="number">${money(l.credit)}</td></tr>`).join('')+`<tr><td><strong>${t('total')}</strong></td><td>—</td><td class="number"><strong>${money(sum('debit'))}</strong></td><td class="number"><strong>${money(sum('credit'))}</strong></td></tr>`)}</section><section class="panel section-gap"><div class="panel-head"><h3>${t('export')}</h3></div><div class="actions">${['customers','accounts','operations','loans','ledger','audit'].map(d=>btn('↓ '+(i18n[state.lang][d]||d),'export','',`data-dataset="${d}"`)).join('')}</div></section>`}
function auditView(){const audit=state.cache.audit;return pageHeader(btn(t('export'),'export','',`data-dataset="audit"`))+`<div class="banner-info">SHA-256 hash chain · ${state.cache.check.audit_chain_valid?'✓ '+t('auditValid'):'⚠ '+t('invalid')}</div><section class="panel">${tb([t('date'),t('actor'),t('event'),t('entity'),t('integrity')],audit.map(a=>`<tr><td>${date(a.created_at)}</td><td><strong>${esc(a.actor||'system')}</strong></td><td class="mono">${esc(a.action)}</td><td>${esc(a.entity)} #${esc(a.entity_id)}</td><td class="mono" title="${esc(a.event_hash)}">${esc(a.event_hash.slice(0,13))}…</td></tr>`).join(''))}</section>`}
function productsView(){const catalog=state.cache.catalog;return pageHeader()+`<section class="panel"><div class="panel-head"><h3>${t('bankingProducts')}</h3></div><div class="feature-grid">${catalog.accounts.map(p=>`<div class="feature"><div class="feature-icon">◫</div><strong>${cap(p.key)}</strong><p>${p.annual_rate_example==null?t('pricing'):`${t('rate')}: ${p.annual_rate_example}%`}</p></div>`).join('')}</div></section><section class="panel section-gap"><div class="panel-head"><h3>${t('lendingProducts')}</h3></div><div class="feature-grid">${catalog.loans.map(p=>`<div class="feature"><div class="feature-icon">↗</div><strong>${cap(p.key)}</strong><p>${t('rate')}: ${p.rate_example}% <span class="muted">(${t('pricing')})</span></p></div>`).join('')}</div></section><section class="panel section-gap"><div class="panel-head"><h3>${t('integrations')}</h3></div><div class="feature-grid">${catalog.integrations.map(p=>`<div class="feature"><div class="feature-icon">⇄</div><strong>${esc(p.name)}</strong><p>${badge('pending')} ${t('sandbox')}</p></div>`).join('')}</div><p class="side-note">${t('nonProd')}</p></section>`}
function settingsView(){const s=state.cache.settings;return pageHeader()+`<div class="banner-info">${t('notProduction')}</div><section class="panel"><div class="metric-line"><span>${t('approvalThreshold')}</span><strong>${money(s.approval_threshold_xaf)}</strong></div><div class="metric-line"><span>${t('alertThreshold')}</span><strong>${money(s.alert_threshold_xaf)}</strong></div><div class="metric-line"><span>Mode</span>${badge('active')} <b>${s.demo_mode}</b></div><div class="metric-line"><span>${t('role')}</span><b>${esc(state.user.role)}</b></div><div class="metric-line"><span>${t('branch')}</span><b>#${state.user.branch_id}</b></div><div class="metric-line"><span>${t('proof')}</span><b>1.0.0</b></div><p class="side-note">${t('settingsWarn')}</p></section><section class="panel section-gap"><div class="panel-head"><h3>${t('regulatory')}</h3></div><p class="side-note">COBAC · CEMAC · BEAC · ANIF · MINFI — ${t('proof')}. ${t('nonProd')}</p><a href="https://www.beac.int/supervision-bancaire/microfinance/reglements-de-microfinance/" target="_blank" rel="noreferrer">BEAC — ${t('regulatory')}</a></section>`}
function searchBox(){return `<div class="search-wrap"><input type="search" id="table-search" value="${attr(state.search)}" placeholder="${attr(t('search'))}" autocomplete="off" aria-label="${attr(t('search'))}"></div>`}
function renderLogin(){document.documentElement.lang=state.lang;document.getElementById('app').innerHTML=`<div class="login-page"><div class="login-visual"><div class="logo" style="border:0;padding:0"><div class="brand-mark">F</div><div><div class="logo-title">FINEC ONE</div><div class="logo-small">CORE BANKING EXPERIENCE</div></div></div><div class="login-hero"><div class="hero-tag">◉ ${t('demo')}</div><h1>${t('loginAsideTitle')}</h1><p>${t('loginAsideDesc')}</p></div><div class="login-footer">FINEC S.A. · CEMAC / Cameroun · DEMO</div></div><div class="login-main"><div class="login-card"><div class="inline-space" style="margin-bottom:33px"><span class="chip">◉ ${t('fake')}</span><button class="top-action" data-action="toggle-lang">${state.lang==='fr'?'EN':'FR'} 🌐</button></div><div class="eyebrow">FINEC / PORTAL</div><h2>${t('loginTitle')}</h2><p class="subtitle">${t('loginSub')}</p><form id="login-form"><div class="form-group"><label>${t('username')}</label><input name="username" required value="admin" autocomplete="username"></div><div class="form-group"><label>${t('password')}</label><input name="password" type="password" required value="Demo2026!" autocomplete="current-password"></div><button class="btn primary login-submit" type="submit">${t('signIn')} &nbsp; →</button></form><div class="login-hint"><b>${t('accountsDemo')}</b>${[['admin','admin'],['agent','teller'],['credit','credit'],['manager','manager'],['conformite','compliance'],['auditeur','auditor']].map(([u,r])=>`<div class="demo-user"><span><strong>${u}</strong> <span class="muted">(${r})</span></span><button data-action="demo-user" data-user="${u}">${t('selectRole')}</button></div>`).join('')}<div style="margin-top:12px;color:#728d81">Password / Mot de passe : <strong>Demo2026!</strong></div></div></div></div></div>`;}
const views={overview,customers:customersView,accounts:accountsView,operations:operationsView,loans:loansView,approvals:approvalsView,compliance:complianceView,branches:branchesView,reports:reportsView,audit:auditView,products:productsView,settings:settingsView};
function render(){document.documentElement.lang=state.lang;document.title='FINEC ONE · '+(state.token&&state.user?t(state.page):'Core Banking Experience');if(!state.token||!state.user){renderLogin();return}let user=state.user;document.getElementById('app').innerHTML=`<div class="app-shell">${navHTML()}<div class="main"><header class="topbar"><div class="inline-space"><button class="top-action mobile-menu" data-action="mobile-menu" aria-label="${t('navigation')}">☰</button><div class="breadcrumbs">FINEC ONE &nbsp; / &nbsp; <strong>${t(state.page)}</strong></div></div><div class="top-right"><span class="chip" style="white-space:nowrap">● DEMO</span><button class="top-action" data-action="toggle-lang" aria-label="Switch language">${state.lang==='fr'?'EN':'FR'} 🌐</button><button class="top-action" data-action="logout" title="${t('logout')}">↪</button><div class="user-badge"><div class="avatar">${esc(user.full_name.slice(0,1))}</div><div><div class="user-name">${esc(user.full_name)}</div><div class="user-role">${esc(user.role)} · ${esc(user.username)}</div></div></div></div></header><main class="page">${views[state.page]()}</main></div></div>`}

/** Modal composer: fields are translated, and HTML is escaped before insertion. */
const field=(name,label,type='text',value='',options=null,extras='')=>{
 const id='field-'+name;
 if(options){return `<div class="form-group"><label for="${id}">${label}</label><select id="${id}" name="${name}" ${extras} required>${options.map(o=>`<option value="${attr(o[0])}" ${String(o[0])===String(value)?'selected':''}>${esc(o[1])}</option>`).join('')}</select></div>`}
 return `<div class="form-group"><label for="${id}">${label}</label><input id="${id}" name="${name}" type="${type}" value="${attr(value)}" ${extras}></div>`;
};
function selectCustomers(verifiedOnly=true){return (state.cache.customers||[]).filter(c=>!verifiedOnly||c.kyc_status==='verified').map(c=>[c.id,`${c.full_name} — ${c.customer_no}`])}
function selectAccounts({active=true}={}){return (state.cache.accounts||[]).filter(a=>(!active||a.status==='active')&&a.kyc_status==='verified').map(a=>[a.id,`${a.account_no} · ${a.customer_name} (${money(a.balance)})`])}
const options=(arr)=>arr.map(k=>[k,t(k)]);
function openModal(title,subtitle,formId,content){document.getElementById('modal-root').innerHTML=`<div class="overlay" id="overlay"><section class="modal" role="dialog" aria-modal="true" aria-label="${attr(title)}"><div class="modal-head"><div><h2>${title}</h2><div class="modal-sub">${subtitle}</div></div><button class="close" data-action="close-modal" aria-label="${t('close')}">×</button></div><form id="${formId}"><div class="form-grid">${content}</div><div class="form-foot"><button type="button" class="btn" data-action="close-modal">${t('cancel')}</button><button type="submit" class="btn primary">${t('confirm')} →</button></div></form></section></div>`;const first=document.querySelector('#modal-root input,#modal-root select');first?.focus()}
function closeModal(){document.getElementById('modal-root').innerHTML=''}
function newCustomer(){if(!can('customers.write'))return denied();openModal(t('newCustomer'),t('customerCreateSub'),'customer-form',[
 field('full_name',t('name'),'text','',null,'required maxlength="120" minlength="2"'),field('phone',t('phone'),'tel','+237 6',null,'required minlength="7"'),
 field('email',t('email'),'email'),field('national_id',t('nationalId'),'text','DEMO-'),
 field('kind',t('kind'),'select','individual',options(['individual','business'])),
 field('branch_id',t('branch'),'select',state.user.branch_id,state.cache.branches.map(b=>[b.id,b.name])),
 field('occupation',t('occupation')),field('risk_level',t('risk'),'select','LOW',[['LOW',t('low')],['MEDIUM',t('medium')],['HIGH',t('high')]])
 ].join(''))}
function newAccount(customerId=null){if(!can('accounts.write'))return denied();const customers=selectCustomers();if(!customers.length)return toast(t('pendingKyc'),true);openModal(t('newAccount'),t('accountOpenSub'),'account-form',[
 field('customer_id',t('customer'),'select',customerId||customers[0][0],customers),
 field('product',t('product'),'select','savings',options(['savings','current','daily','blocked']))
 ].join(''))}
function newOperation(kind='deposit'){
 if(!can('operations.write'))return denied();const accounts=selectAccounts();if(!accounts.length)return toast(t('noData'),true);
 const txKinds=['deposit','collection','withdrawal','transfer','mobile_out'];
 openModal(t('newOp'),t('opCreateSub'),'operation-form',[
 field('kind',t('type'),'select',kind,options(txKinds)),
 field('amount',t('amount'),'number','50000',null,'required min="1" max="100000000" step="1"'),
 `<div class="form-group" id="source-selector">${field('source_account_id',t('source'),'select',accounts[0][0],accounts)}</div>`,
 `<div class="form-group" id="destination-selector">${field('destination_account_id',t('destination'),'select',accounts[0][0],accounts)}</div>`,
 field('channel',t('channel'),'select',kind==='collection'?'daily_collection':'branch',[["branch",t('manual')],["daily_collection",t('collection')],["mobile_money",'Mobile Money / DEMO'],["internal",t('transfer')]]),
 field('note',t('note'),'text','',null,'maxlength="300"')
 ].join(''));setOperationInputs()}
function setOperationInputs(){const kind=document.querySelector('#operation-form [name="kind"]')?.value;if(!kind)return;const src=document.getElementById('source-selector'),dst=document.getElementById('destination-selector');if(src){src.style.display=['deposit','collection'].includes(kind)?'none':'';src.querySelector('select').disabled=['deposit','collection'].includes(kind)}if(dst){dst.style.display=['withdrawal','mobile_out'].includes(kind)?'none':'';dst.querySelector('select').disabled=['withdrawal','mobile_out'].includes(kind)}}
function newLoan(){if(!can('loans.write'))return denied();const customers=selectCustomers();if(!customers.length)return toast(t('noData'),true);openModal(t('newLoan'),t('loanCreateSub'),'loan-form',[
 field('customer_id',t('customer'),'select',customers[0][0],customers),
 field('account_id',t('destination'),'select',null,selectAccounts()),
 field('product',t('product'),'select','commercial',options(['commercial','agriculture','school','consumption','equipment','health'])),
 field('principal',t('principal'),'number','1000000',null,'required min="1000" max="50000000" step="1"'),
 field('rate',t('rate'),'number','12',null,'required min="0" max="40" step="0.1"'),
 field('term_months',t('term'),'number','12',null,'required min="1" max="120" step="1"')
 ].join(''));updateLoanAccounts()}
function updateLoanAccounts(){const cust=document.querySelector('#loan-form [name="customer_id"]');const a=document.querySelector('#loan-form [name="account_id"]');if(!cust||!a)return;const matches=state.cache.accounts.filter(x=>x.customer_id===Number(cust.value)&&x.status==='active');a.innerHTML=matches.map(x=>`<option value="${x.id}">${esc(x.account_no)} · ${cap(x.product)}</option>`).join('')}
function newKyc(id){if(!can('kyc.write'))return denied();let c=state.cache.customers.find(x=>x.id===Number(id));if(!c)return;openModal(t('kyc'),c.full_name+' • '+c.customer_no,'kyc-form',[
 `<input type="hidden" name="customer_id" value="${c.id}">`,
 field('status',t('kycStatus'),'select',c.kyc_status,options(['verified','pending','rejected'])),
 field('risk_level',t('risk'),'select',c.risk_level,[['LOW',t('low')],['MEDIUM',t('medium')],['HIGH',t('high')]])
 ].join(''))}
function newRepay(id){if(!can('operations.write'))return denied();let l=state.cache.loans.find(x=>x.id===Number(id));if(!l)return;openModal(t('repay'),t('loanRepaySub')+' · '+l.loan_no,'repay-form',[
 `<input type="hidden" name="loan_id" value="${l.id}">`,
 `<div class="form-group full"><div class="metric-line"><span>${t('outstanding')}</span><strong>${money(l.outstanding)}</strong></div><div class="metric-line"><span>${t('installment')}</span><strong>${money(l.monthly_payment)}</strong></div></div>`,
 field('amount',t('repayAmount'),'number',Math.min(l.monthly_payment,l.outstanding+Math.round(l.outstanding*l.rate/1200)),null,'required min="1" step="1"')
 ].join(''))}
async function statement(id){const rows=await api('/reports/account/'+id);let a=state.cache.accounts.find(x=>x.id===Number(id));document.getElementById('modal-root').innerHTML=`<div class="overlay" id="overlay"><section class="modal" style="width:min(780px,100%)" role="dialog" aria-modal="true"><div class="modal-head"><div><h2>${t('statement')} · ${esc(a.account_no)}</h2><div class="modal-sub">${esc(a.customer_name)} | ${t('balance')}: ${money(a.balance)}</div></div><button class="close" data-action="close-modal">×</button></div><p class="side-note">${t('statementSub')}</p>${tb([t('date'),t('note'),t('debit'),t('credit')],rows.map(r=>`<tr><td>${date(r.created_at)}</td><td>${esc(r.description)}</td><td>${money(r.debit)}</td><td>${money(r.credit)}</td></tr>`).join(''))}<div class="form-foot">${btn(t('close'),'close-modal')}</div></section></div>`}
function toast(msg,error=false){const div=document.getElementById('toast-root');div.innerHTML=`<div class="toast ${error?'error':''}">${esc(msg)}</div>`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>div.innerHTML='',4400)}
function denied(){toast(t('notAllowed'),true)}
function errorMessage(raw){const map={
 'Insufficient available balance':{fr:'Solde insuffisant.',en:'Insufficient available balance.'},
 'Insufficient funds for loan repayment':{fr:'Fonds insuffisants pour rembourser.',en:'Insufficient funds for loan repayment.'},
 'Maker-checker rule: you cannot approve your own request':{fr:'Séparation des tâches : vous ne pouvez pas approuver votre demande.',en:'Maker-checker: you cannot approve your own request.'},
 'Maker-checker rule: you cannot approve your own loan':{fr:'Vous ne pouvez pas approuver votre propre crédit.',en:'You cannot approve your own loan.'},
 'Customer KYC must be verified before this transaction':{fr:'Le KYC du client doit être validé avant cette opération.',en:'Customer KYC must be verified.'},
 'Verify KYC before opening an account':{fr:'Veuillez valider le KYC avant d’ouvrir le compte.',en:'Verify KYC before opening an account.'},
 'Loan account does not belong to the customer':{fr:'Ce compte ne correspond pas au client sélectionné.',en:'The selected account does not belong to the customer.'},
 'Blocked savings cannot be debited':{fr:'Ce produit d’épargne bloquée ne peut pas être débité.',en:'Blocked savings cannot be debited.'},
 'Pending operation not found':{fr:'Cette opération n’est plus en attente.',en:'This operation is no longer pending.'},
 'Insufficient permissions for this action':{fr:'Votre profil ne permet pas cette opération.',en:'Insufficient permissions.'},
 };return map[raw]?.[state.lang]||raw}
async function refreshAndRender(){await load();render()}
async function submitForm(form){let f=new FormData(form),body=Object.fromEntries(f.entries());const setInt=(keys)=>keys.forEach(k=>{if(body[k]!=null&&body[k]!=='')body[k]=Number(body[k])});
 const submit=form.querySelector('[type=submit]');submit.disabled=true;try{
  if(form.id==='login-form'){
   const res=await api('/auth/login',{method:'POST',body});state.token=res.token;sessionStorage.setItem('finec_token',res.token);await refreshAndRender();toast(t('success'));return;
  }
  if(form.id==='customer-form'){setInt(['branch_id']);await api('/customers',{method:'POST',body})}
  else if(form.id==='account-form'){setInt(['customer_id']);await api('/accounts',{method:'POST',body})}
  else if(form.id==='operation-form'){
   setInt(['amount','source_account_id','destination_account_id']);
   if(['deposit','collection'].includes(body.kind)){delete body.source_account_id}
   if(['withdrawal','mobile_out'].includes(body.kind)){delete body.destination_account_id}
   body.request_key=crypto.randomUUID();
   await api('/operations',{method:'POST',body});
  }
  else if(form.id==='loan-form'){setInt(['customer_id','account_id','principal','rate','term_months']);await api('/loans',{method:'POST',body})}
  else if(form.id==='kyc-form'){const id=Number(body.customer_id);delete body.customer_id;await api('/customers/'+id+'/kyc',{method:'PATCH',body})}
  else if(form.id==='repay-form'){const id=Number(body.loan_id);await api('/loans/'+id+'/repay',{method:'POST',body:{amount:Number(body.amount)}})}
  else return;
  closeModal();state.search='';await refreshAndRender();toast(t('success'));
 }catch(e){toast(errorMessage(e.message),true)}finally{submit.disabled=false}}
async function runAction(el){const a=el.dataset.action,id=el.dataset.id;try{
 if(a==='toggle-lang'){state.lang=state.lang==='fr'?'en':'fr';localStorage.setItem('finec_lang',state.lang);render();return}
 if(a==='close-modal'){closeModal();return}
 if(a==='mobile-menu'){state.mobile=!state.mobile;render();return}
 if(a==='logout'){try{await api('/auth/logout',{method:'POST'})}catch{}sessionStorage.removeItem('finec_token');state.token=null;state.user=null;state.cache={};render();return}
 if(a==='demo-user'){document.querySelector('#login-form input[name="username"]').value=el.dataset.user;document.querySelector('#login-form input[name="password"]').value='Demo2026!';return}
 if(a==='open-customer')return newCustomer();
 if(a==='open-account')return newAccount(id);
 if(a==='open-operation')return newOperation();
 if(a==='open-deposit')return newOperation('deposit');
 if(a==='open-transfer')return newOperation('transfer');
 if(a==='open-loan')return newLoan();
 if(a==='open-kyc')return newKyc(id);
 if(a==='open-repay')return newRepay(id);
 if(a==='open-statement')return await statement(id);
 if(a==='go-approvals'){state.page='approvals';state.search='';render();return}
 if(a==='toggle-account'){await api(`/accounts/${id}/status`,{method:'PATCH',body:{status:el.dataset.status}});await refreshAndRender();return toast(t('success'))}
 if(a==='decide'){
  if(!confirm(`${el.dataset.decision==='approve'?t('approve'):t('reject')} ?`))return;
  const path=el.dataset.kind==='loan'?`/loans/${id}/decision`:`/operations/${id}/decision`;
  await api(path,{method:'POST',body:{decision:el.dataset.decision}});await refreshAndRender();return toast(t('success'));
 }
 if(a==='alert-review'||a==='alert-escalate'){
  await api(`/alerts/${id}`,{method:'PATCH',body:{status:a==='alert-review'?'reviewed':'escalated'}});await refreshAndRender();return toast(t('success'))
 }
 if(a==='export'){
  const res=await api(`/reports/export/${el.dataset.dataset}`,{raw:true});const blob=await res.blob();const url=URL.createObjectURL(blob);const link=document.createElement('a');link.href=url;link.download=`finec_demo_${el.dataset.dataset}.csv`;document.body.append(link);link.click();link.remove();URL.revokeObjectURL(url);return;
 }
 if(a==='check-ledger'){await refreshAndRender();return toast(state.cache.check.balanced?t('balanced'):t('invalid'),!state.cache.check.balanced)}
 }catch(e){toast(errorMessage(e.message),true)}}

document.addEventListener('click',async e=>{const target=e.target.closest('[data-page],[data-action]');if(target){if(target.dataset.page){state.page=target.dataset.page;state.search='';state.mobile=false;closeModal();render();window.scrollTo(0,0)}else await runAction(target)}else if(e.target.id==='overlay')closeModal()});
document.addEventListener('submit',async e=>{if(e.target.matches('#login-form,#customer-form,#account-form,#operation-form,#loan-form,#kyc-form,#repay-form')){e.preventDefault();await submitForm(e.target)}});
document.addEventListener('change',e=>{if(e.target.matches('#operation-form [name="kind"]'))setOperationInputs();if(e.target.matches('#loan-form [name="customer_id"]'))updateLoanAccounts();if(e.target.matches('#loan-form [name="product"]')){const defaults={commercial:12,agriculture:10.5,school:0,consumption:14,equipment:11,health:9};document.querySelector('#loan-form [name="rate"]').value=defaults[e.target.value]}});
document.addEventListener('input',e=>{if(e.target.id!=='table-search')return;state.search=e.target.value.toLowerCase();document.querySelectorAll('.data-table tbody tr').forEach(row=>{row.style.display=row.textContent.toLowerCase().includes(state.search)?'':'none'})});
document.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});

async function bootstrap(){if(!state.token)return render();document.getElementById('app').innerHTML=`<div class="loading">${t('loading')}</div>`;try{await load();render()}catch(e){state.token=null;state.user=null;sessionStorage.removeItem('finec_token');render();toast(errorMessage(e.message),true)}}
bootstrap();

